#include <stdio.h>

static int values[100000];

static bool contains(int n, int x) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (values[mid] == x) {
            return true;
        }
        if (values[mid] < x) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return false;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100000) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    int x;
    while (scanf("%d", &x) == 1) {
        printf("%s\n", contains(n, x) ? "да" : "нет");
    }
    return 0;
}

