static int upper_bound(int n, int x) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (values[mid] <= x) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
