#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 0 || n > 1000) {
        return 0;
    }
    int values[1000];
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    long long total_linear = 0, total_binary = 0;
    int x;
    while (scanf("%d", &x) == 1) {
        int linear = 0;
        int i = 0;
        while (i < n) {
            linear++;
            if (!(values[i] < x)) {
                break;
            }
            i++;
        }
        int binary = 0;
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            binary++;
            if (values[mid] < x) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        printf("%d %d %d\n", lo, linear, binary);
        total_linear += linear;
        total_binary += binary;
    }
    printf("итого: %lld %lld\n", total_linear, total_binary);
    return 0;
}

