#include <stdio.h>

static long long values[100000];

static bool fits(int n, int k, long long limit) {
    int segments = 1;
    long long current = 0;
    for (int i = 0; i < n; i++) {
        if (values[i] > limit) {
            return false;
        }
        if (current + values[i] > limit) {
            segments++;
            current = 0;
        }
        current += values[i];
    }
    return segments <= k;
}

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2 || n < 1 || n > 100000) {
        return 0;
    }
    long long lo = 0, hi = 0;
    for (int i = 0; i < n; i++) {
        scanf("%lld", &values[i]);
        if (values[i] > lo) {
            lo = values[i];
        }
        hi += values[i];
    }
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (fits(n, k, mid)) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    printf("%lld\n", lo);
    return 0;
}

